def assign_default_company(apps, schema_editor):
    """Give every existing user a default membership of the first active company.

    Safe for the current single-company database. Superusers do not need a row
    (they can enter every active company), but the row is harmless and gives the
    UI a default. Additional companies are assigned explicitly in admin.
    """
    Company = apps.get_model("core", "Company")
    UserCompany = apps.get_model("core", "UserCompany")
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    company = Company.objects.filter(is_active=True).order_by("id").first()
    if company is None:
        return
    for user in User.objects.all().iterator():
        UserCompany.objects.get_or_create(
            user=user,
            company=company,
            defaults={"is_default": True, "is_active": True},
        )


